/// Integration scheme used for tracing streamlines.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StreamlineIntegrator {
    /// First-order explicit (Forward) Euler integration.
    EulerForward,
    /// Fourth-order Runge–Kutta integration (RK4).
    RungeKutta4,
}
impl StreamlineIntegrator {
    /// Advance position `pos` by one step of size `dt` through `field`.
    pub(super) fn step(&self, pos: Vec3, dt: f64, field: &dyn Fn(Vec3) -> Vec3) -> Vec3 {
        match self {
            StreamlineIntegrator::EulerForward => {
                let v = field(pos);
                pos + v * dt
            }
            StreamlineIntegrator::RungeKutta4 => {
                let k1 = field(pos);
                let k2 = field(pos + k1 * (dt * 0.5));
                let k3 = field(pos + k2 * (dt * 0.5));
                let k4 = field(pos + k3 * dt);
                pos + (k1 + k2 * 2.0 + k3 * 2.0 + k4) * (dt / 6.0)
            }
        }
    }
}
